import json
import csv
import os
import sys
from datetime import datetime, timedelta
from collections import defaultdict

def parse_date(excel_date):
    """Convert Excel serial date to YYYY-MM-DD string."""
    if excel_date == "":
        return None
    try:
        # Excel date system where 1899-12-30 is day 0
        base_date = datetime(1899, 12, 30)
        date = base_date + timedelta(days=float(excel_date))
        return date.strftime("%Y-%m-%d")
    except:
        return None

def load_lca_disclosure(packet_dir):
    """Load lca_disclosure.csv file."""
    filepath = os.path.join(packet_dir, "lca_disclosure.csv")
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            case_num = row['CASE_NUMBER']
            data[case_num] = {
                'offered_wage': row['WAGE_RATE_OF_PAY_FROM'],
                'prevailing_wage': row['PREVAILING_WAGE'],
                'begin_date': parse_date(row['BEGIN_DATE']),
                'end_date': parse_date(row['END_DATE'])
            }
    return data

def process_packet(packet_dir, manifest_file):
    """Main processing function."""
    # Load manifest
    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    # Load data from files
    lca_data = load_lca_disclosure(packet_dir)

    # Prepare result structure
    result = {}

    # Process each pair
    for pair in manifest['pairs']:
        rule_id, entity = pair.split("::", 1)
        facts = manifest['facts'][rule_id]

        # Initialize fact results for this pair
        pair_result = {}

        # Get entity data
        entity_data = lca_data.get(entity)

        for fact in facts:
            if rule_id == "lca.wage_105":
                if fact == "offered wage":
                    if entity_data and entity_data['offered_wage']:
                        # Convert to decimal string
                        try:
                            value = str(float(entity_data['offered_wage']))
                            pair_result[fact] = [value, "lca_disclosure"]
                        except:
                            pair_result[fact] = "ABSENT"
                    else:
                        pair_result[fact] = "ABSENT"

                elif fact == "prevailing wage":
                    if entity_data and entity_data['prevailing_wage']:
                        try:
                            value = str(float(entity_data['prevailing_wage']))
                            pair_result[fact] = [value, "lca_disclosure"]
                        except:
                            pair_result[fact] = "ABSENT"
                    else:
                        pair_result[fact] = "ABSENT"

            elif rule_id == "lca.three_years":
                if fact == "begin date":
                    if entity_data and entity_data['begin_date']:
                        pair_result[fact] = [entity_data['begin_date'], "lca_disclosure"]
                    else:
                        pair_result[fact] = "ABSENT"

                elif fact == "end date":
                    if entity_data and entity_data['end_date']:
                        pair_result[fact] = [entity_data['end_date'], "lca_disclosure"]
                    else:
                        pair_result[fact] = "ABSENT"

        result[pair] = pair_result

    return json.dumps(result, indent=2)

if __name__ == "__main__":
