import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(filepath):
    """Read CSV file and return list of dictionaries."""
    data = []
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            data.append(row)
    return data

def excel_date_to_iso(excel_date_str):
    """Convert Excel serial date number to ISO date string YYYY-MM-DD."""
    if not excel_date_str:
        return None
    try:
        # Excel date is days since 1899-12-30 (with 1900 leap year bug)
        days = int(float(excel_date_str))
        base = datetime(1899, 12, 30)
        date_obj = base + timedelta(days=days)
        return date_obj.strftime('%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def process_packet(packet_dir, manifest):
    """Process the packet according to the manifest."""
    # Load manifest
    pairs = manifest["pairs"]
    facts = manifest["facts"]

    # Prepare result structure
    result = {}

    # Read all CSV files in packet directory
    csv_files = {}
    for filepath in Path(packet_dir).glob("*.csv"):
        filename = filepath.stem  # Remove extension
        csv_files[filename] = read_csv_file(filepath)

    # Group pairs by rule_id and entity
    pair_map = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        if rule_id not in pair_map:
            pair_map[rule_id] = {}
        pair_map[rule_id][entity] = True

    # Process each rule
    for rule_id, entities in pair_map.items():
        # Get fact names for this rule
        rule_facts = facts.get(rule_id, [])

        # Determine which CSV file to use based on rule_id
        csv_filename = None
        if rule_id == "lca.wage_105" or rule_id == "lca.three_years":
            csv_filename = "lca_disclosure"

        if not csv_filename or csv_filename not in csv_files:
            continue

        csv_data = csv_files[csv_filename]

        # Create mapping from CASE_NUMBER to row
        case_to_row = {}
        for row in csv_data:
            case_num = row.get("CASE_NUMBER")
            if case_num:
                case_to_row[case_num] = row

        # Process each entity for this rule
        for entity in entities:
            pair_key = f"{rule_id}::{entity}"
            result[pair_key] = {}

            if entity not in case_to_row:
                # Entity not found in CSV
                for fact_name in rule_facts:
                    result[pair_key][fact_name] = "ABSENT"
                continue

            row = case_to_row[entity]

            if rule_id == "lca.wage_105":
                # Process wage facts
                wage_facts = {}

                # Offered wage from WAGE_RATE_OF_PAY_FROM
                offered_wage_str = row.get("WAGE_RATE_OF_PAY_FROM", "").strip()
                if offered_wage_str:
                    try:
                        # Remove commas if present
                        offered_wage_str = offered_wage_str.replace(',', '')
                        offered_wage = float(offered_wage_str)
                        wage_facts["offered wage"] = [str(offered_wage), csv_filename]
                    except (ValueError, AttributeError):
                        wage_facts["offered wage"] = "ABSENT"
                else:
                    wage_facts["offered wage"] = "ABSENT"

                # Prevailing wage from PREVAILING_WAGE
                prevailing_wage_str = row.get("PREVAILING_WAGE", "").strip()
                if prevailing_wage_str:
                    try:
                        # Remove commas if present
                        prevailing_wage_str = prevailing_wage_str.replace(',', '')
                        prevailing_wage = float(prevailing_wage_str)
                        wage_facts["prevailing wage"] = [str(prevailing_wage), csv_filename]
                    except (ValueError, AttributeError):
                        wage_facts["prevailing wage"] = "ABSENT"
                else:
                    wage_facts["prevailing wage"] = "ABSENT"

                # Assign facts to result
                for fact_name in rule_facts:
                    result[pair_key][fact_name] = wage_facts.get(fact_name, "ABSENT")

            elif rule_id == "lca.three_years":
                # Process date facts
                date_facts = {}

                # Begin date from BEGIN_DATE
                begin_date_str = row.get("BEGIN_DATE", "").strip()
                if begin_date_str:
                    iso_begin_date = excel_date_to_iso(begin_date_str)
                    if iso_begin_date:
                        date_facts["begin date"] = [iso_begin_date, csv_filename]
                    else:
                        date_facts["begin date"] = "ABSENT"
                else:
                    date_facts["begin date"] = "ABSENT"

                # End date from END_DATE
                end_date_str = row.get("END_DATE", "").strip()
                if end_date_str:
                    iso_end_date = excel_date_to_iso(end_date_str)
                    if iso_end_date:
                        date_facts["end date"] = [iso_end_date, csv_filename]
                    else:
                        date_facts["end date"] = "ABSENT"
                else:
                    date_facts["end date"] = "ABSENT"

                # Assign facts to result
                for fact_name in rule_facts:
                    result[pair_key][fact_name] = date_facts.get(fact_name, "ABSENT")

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Read manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Process packet
    result = process_packet(packet_dir, manifest)

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

