import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(excel_date):
    """Convert Excel serial date to YYYY-MM-DD string."""
    if excel_date == "":
        return None
    try:
        # Excel's epoch is 1899-12-30, but there's a known off-by-2 error
        # Actually Excel dates start from 1900-01-00 (with bug), so we adjust
        # Using datetime.fromordinal with offset
        base_date = datetime(1899, 12, 30)
        days = int(float(excel_date))
        date_obj = base_date + timedelta(days=days)
        return date_obj.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def load_lca_disclosure(packet_dir):
    """Load lca_disclosure.csv and return dict by CASE_NUMBER."""
    file_path = Path(packet_dir) / "lca_disclosure.csv"
    data = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            case_num = row['CASE_NUMBER']
            # Convert dates
            begin_date = parse_date(row['BEGIN_DATE'])
            end_date = parse_date(row['END_DATE'])
            # Handle wages - they might be empty or have decimals
            offered_wage = row['WAGE_RATE_OF_PAY_FROM'].strip()
            prevailing_wage = row['PREVAILING_WAGE'].strip()

            # Convert wage strings to appropriate format
            # Keep as string but ensure proper decimal format
            if offered_wage:
                try:
                    offered_wage = str(float(offered_wage))
                except ValueError:
                    offered_wage = ""

            if prevailing_wage:
                try:
                    prevailing_wage = str(float(prevailing_wage))
                except ValueError:
                    prevailing_wage = ""

            data[case_num] = {
                'begin_date': begin_date,
                'end_date': end_date,
                'offered_wage': offered_wage,
                'prevailing_wage': prevailing_wage,
                'document': 'lca_disclosure'
            }
    return data

def process_pair(pair, rule_id, entity, lca_data, facts):
    """Process a single pair and return its facts."""
    result = {}

    if entity not in lca_data:
        # Entity not found in data
        for fact_name in facts[rule_id]:
            result[fact_name] = "ABSENT"
        return result

    record = lca_data[entity]

    for fact_name in facts[rule_id]:
        if fact_name == 'offered wage':
            value = record['offered_wage']
            if not value:
                result[fact_name] = "ABSENT"
            else:
                result[fact_name] = [value, record['document']]

        elif fact_name == 'prevailing wage':
            value = record['prevailing_wage']
            if not value:
                result[fact_name] = "ABSENT"
            else:
                result[fact_name] = [value, record['document']]

        elif fact_name == 'begin date':
            value = record['begin_date']
            if not value:
                result[fact_name] = "ABSENT"
            else:
                result[fact_name] = [value, record['document']]

        elif fact_name == 'end date':
            value = record['end_date']
            if not value:
                result[fact_name] = "ABSENT"
            else:
                result[fact_name] = [value, record['document']]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load data from files
    lca_data = load_lca_disclosure(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')
        result = process_pair(pair, rule_id, entity, lca_data, manifest['facts'])
        output[pair] = result

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

